entries[319210] = { ["name"] = "Geselligkeit", ["text"] = "Seelenbandefähigkeit\nWenn sich mindestens 2 Verbündete innerhalb von 8 Metern aufhalten, wird Eure Vielseitigkeit für 5 Sek. um 3% erhöht. Wenn dieser Effekt endet, erhalten 2 Verbündete in der Nähe 33% dieses Bonus für 5 Sek., wonach er wieder auf Euch übergeht." }
entries[319211] = { ["name"] = "Besänftigende Stimme", ["text"] = "Seelenbandefähigkeit\nWenn die Betäubungs-, Bewegungsunfähigkeits- und Handlungsunfähigkeitseffekte Eurer Klasse ablaufen oder gebannt werden, wird die Bewegungsgeschwindigkeit Eures Ziels um 90% verringert. Dieser Effekt nimmt im Verlauf von 2 Sek. rapide ab." }
entries[319212] = { ["name"] = "Züchtigung", ["text"] = "40 Meter Reichweite\nKanalisiert (Wirken in 9 sek.)\nBefreit das Ziel von der Bürde seiner Sünden und erschafft so im Verlauf von 9 Sek. bis zu 0 Manifestationen." }
entries[319213] = { ["name"] = "Mächtiger Kokon", ["text"] = "Seelenbandefähigkeit\n10% Eurer erhaltenen oder hervorgerufenen überschüssigen Heilung verbleiben als Schild in Höhe von bis zu 10% der Gesundheit des Zaubernden auf dem Ziel. Hält 5 Sek. lang an." }
entries[319214] = { ["name"] = "Feenstaub", ["text"] = "Seelenbandefähigkeit\nWenn Ihr tiefer als 20 Meter fallt, verlangsamt Feenstaub für die nächsten 30 Sek. Euren Fall. Dieser Effekt kann nur einmal alle 1 Min. auftreten." }
