entries[319216] = { ["name"] = "Schlafwandler", ["text"] = "Seelenbandefähigkeit\nNachdem Ihr 60 Sek. in einem Ruhebereich verbracht habt, wird Eure Bewegungsgeschwindigkeit 30 Min. lang um 20% erhöht." }
entries[319217] = { ["name"] = "Kapselpfleger", ["text"] = "Seelenbandefähigkeit\nWenn Ihr Schaden erleidet, der sonst tödlich wäre, werdet Ihr stattdessen in einem Wildsamen verjüngt und erhaltet dabei im Verlauf von 10 Sek. 30% Eurer Gesundheit zurück. Wenn der Wildsamen während dieser Zeit mehr als (Angriffskraft * 10) Schaden erleidet, sterbt Ihr.\n\nDieser Effekt kann nur einmal alle 10 Min. auftreten." }
