entries[319343] = { ["name"] = "Seismischer Donner", ["text"] = "Sofort\nLässt die Erde innerhalb von 8 Metern um den Zielort erzittern und aufbrechen. Gegner erleiden im Verlauf von 6 Sek. [Zaubermacht * 0.5 * 6 * (1 + Vielseitigkeit) * 0.9 * 1 * 1 * 1 * 1 ] körperlichen Schaden und werden mit einer Chance von 5% zu Boden gestoßen. Mehrere Einsätze von 'Erdbeben' können sich überlappen.\n\nDieser Zauber wird gegen einen ausgewählten Zielort eingesetzt." }
