entries[319347] = { ["name"] = "Seelenpein hervorrufen", ["text"] = "Sofort\nN'Zoth dringt in den Verstand der Spielercharaktere ein und beschwört ihre finstersten Gedanken, was ihnen 8 Sek. lang alle 5.2 Sek. 13289 Schattenschaden zufügt.\n\nBeim Ablauf explodiert 'Seelenpein hervorrufen', fügt Spielercharakteren innerhalb von 4 Metern 9381 Schattenschaden zu und hinterlässt eine Lache der Seelenpein, die nach ihrem Erscheinen für kurze Zeit wächst.\n\nJedes Mal, wenn N'Zoth der Verderber 'Seelenpein hervorrufen' einsetzt, wachsen alle bestehenden Lachen weiter an." }
entries[319348] = { ["name"] = "Seelenpein hervorrufen", ["text"] = "Unbegrenzte Reichweite\nSofort\nN'Zoth dringt in den Verstand der Spielercharaktere ein und beschwört ihre finstersten Gedanken, was ihnen 8 Sek. lang alle 5.2 Sek. 13289 Schattenschaden zufügt.\n\nBeim Ablauf explodiert 'Seelenpein hervorrufen', fügt Spielercharakteren innerhalb von 4 Metern 9381 Schattenschaden zu und hinterlässt eine Lache der Seelenpein, die nach ihrem Erscheinen für kurze Zeit wächst.\n\nJedes Mal, wenn N'Zoth der Verderber 'Seelenpein hervorrufen' einsetzt, wachsen alle bestehenden Lachen weiter an." }
