entries[319353] = { ["name"] = "Flammen des Wahnsinns", ["text"] = "Unbegrenzte Reichweite\nSofort\nDie Flammen des Wahnsinns überwältigen Spielercharaktere innerhalb von 6 Metern, verursachen beim Kontakt 30 Feuerschaden und entziehen 20 geistige Gesundheit.\n\nDie Flammen verbrennen den Spielercharakter weiter, fügen ihm alle 2 Sek. 12 Feuerschaden zu und desorientieren ihn für 6 Sek.\n\nBrennende Spielercharaktere geben diesen Effekt regelmäßig an andere Spielercharaktere innerhalb vom 6 Metern weiter." }
